import pytest
from event_packet import EventPacket
from sequencer import sequence_stream_batch

def test_stream_sequencing():
    # Create packets with same severity but different stream_ids
    p1 = EventPacket("s1", 9, "critical1")
    p2 = EventPacket("s2", 9, "critical2")

    # Sequence them
    result = sequence_stream_batch([p1, p2])

    # Should maintain stable ordering based on stream_id
    assert result[0].stream_id == "s1"
    assert result[1].stream_id == "s2"
